# -*- coding: utf-8 -*-
"""MANAPRINT - Generateur CALLER (A4 portrait, 16 cartons/feuille).

REGLE ABSOLUE : le decor plus bas EST la planche de Maeva, relevee au trait
   sur sa nouvelle maquette CALLER (le cadre, le titre << CALLER >> avec rayons
   et etoiles, le MICRO, les 6 cases B . G . G . O . O . B et les pastilles
   7/15/32 et 46/60/75). RIEN n'a ete redessine : on ECRIT seulement les 6
   numeros et le numero de serie.

LA REGLE DU JEU (inchangee) : SIX numeros -
   2x B (1-15, en haut et en bas) . 2x G (46-60, a gauche) .
   2x O (61-75, a droite). Le crieur sort 1-15 et 46-75 (le 16-45 n'existe pas).

L'ARC-EN-CIEL EST CARTON PAR CARTON. En N&B au gris #555555.
"""
import io
import random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4
from reportlab.lib import colors
from reportlab.lib.units import mm
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont

try:
    from generators import securite as _sec
except Exception:
    try:
        import securite as _sec
    except Exception:
        _sec = None

